RECHT = "touren.besetzung"


def recht_geben(apps, schema_editor):
    """Das Büro darf die Besetzung jeder Tour beim Start ändern (ADR 0150); Fahrer und Beifahrer
    nur die der Tour, auf der sie selbst eingetragen sind – dafür braucht es kein Recht."""
    for rolle in apps.get_model("konten", "Rolle").objects.filter(gruppe__name="Büro"):
        if RECHT not in rolle.rechte:
            rolle.rechte = [*rolle.rechte, RECHT]
            rolle.save()


def fahrtage_leeren(apps, schema_editor):
    """Bisher galten die Fahrtage einer Tour aus dem Fahrerplan nicht; jetzt grenzen sie ein.
    Damit keine vorhandene Tour dadurch seltener fährt, werden ihre (bisher wirkungslosen)
    Fahrtage geleert."""
    Tour = apps.get_model("touren", "Tour")
    Tour.objects.filter(fahrdienst_tour__isnull=False).exclude(fahrtage="").update(fahrtage="")


def recht_nehmen(apps, schema_editor):
    for rolle in apps.get_model("konten", "Rolle").objects.all():
        if RECHT in rolle.rechte:
            rolle.rechte = [c for c in rolle.rechte if c != RECHT]
            rolle.save()


